def transform(g):
    h, w = len(g), len(g[0])
    out = [[0] * w for _ in range(h)]
    seen = set()
    for r in range(h):
        for c in range(w):
            col = g[r][c]
            if col in (0, 6) or (r, c) in seen:
                continue
            q, comp = [(r, c)], []
            seen.add((r, c))
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == col:
                        seen.add((yy,xx)); q.append((yy,xx))
            if len(comp) >= 2:
                a, b = min(y for y,x in comp), max(y for y,x in comp)
                l, rr = min(x for y,x in comp), max(x for y,x in comp)
                if len(comp) / ((b-a+1)*(rr-l+1)) >= .55:
                    for y in range(a,b+1):
                        for x in range(l,rr+1): out[y][x] = col
    return out
